import { expect, test } from '../fixtures';

/** A secret the flow was driven with. Set it in the environment or in sova/.env. */
function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) throw new Error(`${name} is not set. Add it to sova/.env or the environment.`);
  return value;
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Challenge correct flag scores', async ({ page }) => {
  await test.step('Open the login page', async () => {
    await page.goto('/login');
  });

  await test.step('Type the user name', async () => {
    await page.getByRole('textbox', { name: 'User Name or Email', exact: true }).fill(env('SOLVER_NAME'));
  });

  await test.step('Type the password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill(env('SOLVER_PASSWORD'));
  });

  await test.step('Press Submit', async () => {
    await page.getByRole('button', { name: 'Submit', exact: true }).click();
  });

  await test.step('Open the challenges', async () => {
    await page.goto('/challenges');
  });

  await test.step('Open Warmup', async () => {
    await page.getByRole('button', { name: 'Warmup 100', exact: true }).click();
  });

  await test.step('Type a flag', async () => {
    await page.locator('input[name=submission]').fill('flag{warmup}');
  });

  await test.step('Submit the flag', async () => {
    await page.getByRole('button', { name: 'Submit', exact: true }).click();
  });

  await test.step('The flag is accepted', async () => {
    await expect(page.locator('text=Correct')).toBeVisible();
  });

  await test.step('Open the scoreboard', async () => {
    await page.goto('/scoreboard');
  });

  await test.step('The solver is listed', async () => {
    await expect(page.locator('a >> text=qa-solver >> visible=true >> nth=0')).toBeVisible();
  });

  await test.step('The solver has the 100 points', async () => {
    await expect(page.locator('td >> text=100 >> visible=true >> nth=0')).toBeVisible();
  });
});
